contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        c.Put{value: amount}(lockTime); if (__ESBMC_reverted()) return;

        (uint afterUnlock, uint afterBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        assert((afterBal - beforeBal) + (cBalAfter - cBalBefore) == amount);
    }

    receive() external payable {}
}

